// Every week, asks Claude to sum up the project in one PPM chat. Each week's turn goes to the
// same chat (one key), so it can compare with the weeks before; the answer comes to you as a
// notification that opens that chat.
export default async function main(ctx) {
  const { prompt, title } = ctx.inputs;
  const turn = await ctx.ai.chat("weekly-summary", prompt, { title, timeoutMs: 20 * 60_000 });
  if (turn.busy) throw new Error("the summary chat is busy: a turn is still running in it");
  if (!turn.ok) throw new Error(turn.error || "the summary turn failed");
  await ctx.notify({ title, body: turn.text.slice(0, 500), ...(turn.sessionId && { sessionId: turn.sessionId }) });
}
